// What the server takes from the tools library, blitz-format and blitz-tidy. They share names with the compiler's headers
// (keywords.hpp, config.hpp, the namespace blitz::format), so they are used from translation units of their own.
#pragma once
#include <filesystem>
#include <string>
#include <string_view>
#include <vector>

namespace blitz::lsp::bridge {
	/** Whether the word (any case) is a keyword of the language. */
	bool is_keyword(std::string_view word);

	/** All bytes of the file, throws std::runtime_error. */
	std::string read_file(std::filesystem::path const& file);

	/** Every .bb file beneath the folder (links are not followed), sorted. Empty if the folder can't be read. */
	std::vector<std::filesystem::path> find_sources(std::filesystem::path const& folder);

	/** The source formatted with blitz-format. Without a configuration file next to the program (or in a folder above it)
	 * the indentation is the one of the editor: tabs, or spaces of the given width (0 for the default of blitz-format).
	 * Throws std::runtime_error if the program can't be formatted. */
	std::string format_text(std::string const& source, std::filesystem::path const& file, bool use_tabs, int tab_width, bool editor_indentation);

	/** The source after blitz-tidy. ok is false if the program does not compile, then nothing was changed. */
	std::string tidy_text(std::string const& source, std::filesystem::path const& file, std::filesystem::path const& userlibs_dir, bool& ok);
} // namespace blitz::lsp::bridge
